  const parseInline = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, i) => 
      part.startsWith('**') && part.endsWith('**') 
      ? <strong key={i} className="text-black font-bold">{part.slice(2, -2)}</strong> 
