                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        currentTable = [];
      }
      isInsideTable = false;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();

      if (trimmed.startsWith('Bondowoso,')) {
          flushTable(idx);
          elements.push(
            <div key={`sig-${idx}`} className="mt-12 ml-auto w-72 text-left text-sm">
