                <div ref={printAreaRef} className="bg-white shadow-xl mx-auto w-full p-[15mm] text-black rounded-sm min-h-[1000px] document-body printable-area">
                  {renderFormattedContent(result)}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

