const parseBool = (val: any): boolean => {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') {
    const s = val.toLowerCase().trim();
    return s === 'true' || s === '1' || s === 'yes' || s === 'aktif';
  }
  if (typeof val === 'number') return val === 1;
  return false;
};

